const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const option=(values,selected)=>Object.entries(values).map(([key,value])=>`<option value="${escape(key)}" ${key===selected?'selected':''}>${escape(t(value))}</option>`).join('');
const input=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" value="${escape(value)}" type="${type}" ${extra}></label>`;
const doseMenu=(label,name,value)=>`<label>${label}<select name="${name}" aria-label="${label}">${Array.from({length:51},(_,n)=>`<option value="${n}" ${n===value?'selected':''}>${n} g</option>`).join('')}</select></label>`;
const check=(label,name)=>`<label class="check"><input type="checkbox" name="${name}">${label}</label>`;
let db,entries=[],recipe=null,timerStart=null,elapsed=0,busy=false,selected={equipment:'',bean:'',preference:'balanced',dose:18,drink:'espresso',strength:'standard'};
let equipmentDirectory=null,beanOptions=null,connectionKey='Saved on this device';
const grindDrafts=new Map();
const scope=()=> 'guest'; // Keep the existing local library; never merge old account scopes implicitly.
const data=kind=>entries.filter(e=>e.kind===kind).map(e=>JSON.parse(e.payload));
const toast=message=>{const host=$('#dialog').open?$('#dialog'):$('#editor').open?$('#editor'):$('#dialog');if(host.open){let feedback=host.querySelector('.dialog-notice');if(!feedback){feedback=document.createElement('p');feedback.className='dialog-notice error';feedback.setAttribute('role','status');host.append(feedback);}feedback.textContent=message;}$('#notice').textContent=message;$('#notice').hidden=false;clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>{$('#notice').hidden=true;},9000);};
const modal=html=>{sheetOrigin=null;$('#dialog').classList.remove('equipment-dialog','feedback-dialog','photo-dialog','grind-dialog');$('#dialog .dialog-notice')?.remove();$('#dialog-content').innerHTML=html;$('#dialog').showModal();};
