function bagPhoto(id){return data('photo').filter(p=>p.beanId===id).sort((a,b)=>b.created.localeCompare(a.created))[0]?.image||'';}
const reduceMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let sheetOrigin=null,closingSheet=false;
function morphSheet(source){
 sheetOrigin=source?.getBoundingClientRect();const d=$('#dialog');
 if(!sheetOrigin||reduceMotion())return;
 const to=d.getBoundingClientRect(),from=sheetOrigin;
 d.animate([{transform:`translate(${from.x+from.width/2-to.x-to.width/2}px,${from.y+from.height/2-to.y-to.height/2}px) scale(${Math.max(.15,from.width/to.width)},${Math.max(.15,from.height/to.height)})`,opacity:.25,borderRadius:'24px'},{transform:'none',opacity:1,borderRadius:getComputedStyle(d).borderRadius}],{duration:340,easing:'cubic-bezier(.2,.75,.2,1)'});
}
async function closeSheet(){
 if(closingSheet)return;closingSheet=true;const d=$('#dialog');
 try{if(sheetOrigin&&!reduceMotion()&&d.open){const to=d.getBoundingClientRect(),from=sheetOrigin;await d.animate([{transform:'none',opacity:1},{transform:`translate(${from.x+from.width/2-to.x-to.width/2}px,${from.y+from.height/2-to.y-to.height/2}px) scale(${Math.max(.15,from.width/to.width)},${Math.max(.15,from.height/to.height)})`,opacity:0}],{duration:200,easing:'ease-in'}).finished;}d.close();}finally{closingSheet=false;sheetOrigin=null;}
}
function grindKey(r){return JSON.stringify([r.equipment.id,r.bean.id,r.dose,r.preference,r.drink,r.request?.strength]);}
function draftGrind(r){return grindDrafts.get(grindKey(r))??String(r.grindData?.value??r.grindData?.start??'');}
function usableScale(e){const s=grindScale(e);return s&&Number.isFinite(s.min)&&Number.isFinite(s.max)&&Number.isFinite(s.step)&&s.step>0?s:null;}
function grindFace(r){
 const scale=usableScale(r.equipment),value=draftGrind(r),valid=scale&&value!==''&&Number.isFinite(Number(value));
 let html=dialFace(value||'—','GRIND SETTING',scale?scale.max-scale.min:6,valid?Number(value)-scale.min:0);
 html=html.replace('<span>MIN : SEC</span>','<span>'+(scale?'DIAL VALUE':'YOUR REFERENCE')+'</span>').replace('<div class="dial-display">','<button type="button" class="dial-display" id="grind-readout" aria-label="Edit grind setting">').replace('</span></div></div>','</span></button></div>');
 if(scale)html=html.replace(/(<text[^>]*>)([^<]*)(<\/text>)/g,(()=>{let i=0;return(_,a,b,c)=>a+Number((scale.min+(scale.max-scale.min)*(i++)/6).toFixed(1))+c;})());
 else html=html.replace(/<g class="dial-numbers">.*?<\/g>/,'').replace('class="dial-hand"','class="dial-hand uncalibrated"');
 return `<div class="grind-instrument ${scale?'':'manual-reference'}" ${scale?`role="slider" tabindex="0" aria-label="Grind setting" aria-valuemin="${scale.min}" aria-valuemax="${scale.max}" aria-valuenow="${valid?value:scale.min}" aria-valuetext="${escape(value||'Not set')}"`:''}>${html}</div><p class="grind-status">${grindDrafts.has(grindKey(r))?'Unsaved trial · not yet brewed':value?'Starting reference · confirm on your grinder':'Set your own reference'}</p>${scale?`<div class="dial-controls"><button type="button" id="grind-down" aria-label="Decrease grind setting">−</button><span>${scale.finer==='lower'?'Finer ← → Coarser':'Coarser ← → Finer'}</span><button type="button" id="grind-up" aria-label="Increase grind setting">+</button></div>`:''}`;
}
function homeCupHTML(e,b,resume){
 let r;try{r=recommend(e,b,selected.preference,selected.dose,data('brew'),{drink:selected.drink,strength:selected.strength});}catch{r=null;}
 const beans=data('bean'),index=beans.findIndex(x=>x.id===b.id);
 return `<section class="panel next-cup" id="continue-card"><div class="bag-stage" aria-label="Choose a bag">${beans.length>1?'<button type="button" id="previous-bag" aria-label="Previous bag">‹</button>':''}<div class="bag-slide">${beanObject(b)}<h2>${escape(b.name)}</h2><p class="bean-caption">${escape(b.batch)} · ${escape(t(roasts[b.roast]))}</p></div>${beans.length>1?'<button type="button" id="next-bag" aria-label="Next bag">›</button>':''}</div><div class="bag-dots" aria-label="Your bags">${beans.map((x,i)=>`<button type="button" data-select-bag="${i}" aria-label="Select ${escape(x.name)}" aria-pressed="${i===index}"></button>`).join('')}</div>${r?grindFace(r):'<p class="muted">Confirm your setup and roast level below.</p>'}${resume?`<p class="last-cup-line">Last cup · ${escape(t(tastes[resume.feedback.taste]))} · ${clockText(resume.feedback.seconds)}</p>`:''}<button type="button" class="primary" id="continue-brew">Brew this cup <span aria-hidden="true">→</span></button></section>`;
}
function currentPreview(){const f=$('#brew-form');if(!f)return recipe;const v=Object.fromEntries(new FormData(f));try{return recommend(data('equipment').find(e=>e.id===v.equipment),data('bean').find(b=>b.id===v.bean),v.preference,Number(v.dose),data('brew'),{drink:v.drink,strength:v.strength});}catch{return null;}}
function bindRitual(){
 const r=recipe||currentPreview();if($('#edit-grind'))$('#edit-grind').onclick=()=>editGrind(recipe,$('#edit-grind'));
 if($('#grind-readout')&&r)$('#grind-readout').onclick=()=>editGrind(r,$('#grind-readout'));
 const scale=r&&usableScale(r.equipment),host=$('.grind-instrument');
 if(scale&&host){
  const update=n=>{const value=Number((scale.min+Math.min(Math.floor((scale.max-scale.min)/scale.step+1e-8),Math.round((Math.max(scale.min,Math.min(scale.max,n))-scale.min)/scale.step))*scale.step).toFixed(8));if(value>scale.max)return;grindDrafts.set(grindKey(r),String(value));host.setAttribute('aria-valuenow',value);host.setAttribute('aria-valuetext',String(value));host.querySelector('.dial-display strong').textContent=value;host.querySelector('.dial-hand').setAttribute('transform',`rotate(${-90+(value-scale.min)/(scale.max-scale.min)*180} 160 164)`);$('.grind-status').textContent='Unsaved trial · not yet brewed';};
  const step=n=>update((Number(draftGrind(r))||scale.min)+n*scale.step);
  $('#grind-down').onclick=()=>step(-1);$('#grind-up').onclick=()=>step(1);
  host.onkeydown=e=>{if(e.target!==host)return;const k=e.key;if(['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'].includes(k)){e.preventDefault();if(k==='Home')update(scale.min);else if(k==='End')update(scale.max);else step(['ArrowLeft','ArrowDown'].includes(k)?-1:1);}};
  let dragging=false;const point=e=>{const b=host.querySelector('svg').getBoundingClientRect(),x=e.clientX-b.x-b.width/2,y=e.clientY-b.y-b.width*164/320,angle=Math.atan2(-y,x);update(scale.min+(1-Math.max(0,Math.min(Math.PI,angle))/Math.PI)*(scale.max-scale.min));};
  host.onpointerdown=e=>{if(e.target.closest('button'))return;dragging=true;host.setPointerCapture(e.pointerId);point(e);};host.onpointermove=e=>{if(dragging)point(e);};host.onpointerup=host.onpointercancel=()=>dragging=false;
 }
 const beans=data('bean'),stage=$('.bag-stage');let switching=false;
 const select=async(index,direction)=>{if(switching||index<0||index>=beans.length||beans[index].id===selected.bean)return;switching=true;const slide=$('.bag-slide');if(slide&&!reduceMotion())await slide.animate([{transform:getComputedStyle(slide).transform,opacity:1},{transform:`translateX(${-direction*100}%)`,opacity:0}],{duration:170,easing:'ease-in'}).finished;selected.bean=beans[index].id;recipe=null;elapsed=0;timerStart=null;render();const next=$('.bag-slide');if(next&&!reduceMotion())next.animate([{transform:`translateX(${direction*100}%)`,opacity:0},{transform:'none',opacity:1}],{duration:240,easing:'ease-out'});};
 const index=()=>Math.max(0,beans.findIndex(b=>b.id===($('#brew-form')?.elements.bean.value||selected.bean)));
 if($('#previous-bag'))$('#previous-bag').onclick=()=>select((index()-1+beans.length)%beans.length,-1);
 if($('#next-bag'))$('#next-bag').onclick=()=>select((index()+1)%beans.length,1);
 document.querySelectorAll('[data-select-bag]').forEach(b=>b.onclick=()=>select(Number(b.dataset.selectBag),Number(b.dataset.selectBag)>index()?1:-1));
 if(stage&&beans.length>1){let start=null;stage.onpointerdown=e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY};stage.setPointerCapture(e.pointerId);};stage.onpointermove=e=>{if(!start||reduceMotion())return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>Math.abs(dy))stage.querySelector('.bag-slide').style.transform=`translateX(${Math.max(-160,Math.min(160,dx))}px)`;};stage.onpointerup=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy))select((index()+(dx<0?1:-1)+beans.length)%beans.length,dx<0?1:-1);else stage.querySelector('.bag-slide').style.transform='';};stage.onpointercancel=()=>{start=null;stage.querySelector('.bag-slide').style.transform='';};}
}
function editGrind(r,source){
 const scale=usableScale(r.equipment),value=draftGrind(r);
 modal(`<p class="eyebrow">${escape(r.bean.name)} · ${escape(r.equipment.grinder)}</p><h2>Your next grind</h2><form id="grind-form">${input('Setting on your grinder','setting',value,'text','maxlength="100" required')}<p class="field-help">${scale?`Your scale: ${scale.min}–${scale.max}, steps of ${scale.step}. ${escape(r.equipment.calibration||'Use your confirmed zero reference.')}`:'Copy the full setting, including turns or inner-ring offsets. A dial needs a confirmed range and step in Setup.'}</p><p class="muted">A plan for the next cup. Confirm what you actually used when saving your brew.</p><div class="actions"><button class="primary">Use for this cup</button><button type="button" id="reset-grind">Reset</button></div></form>`);
 $('#dialog').classList.add('grind-dialog');morphSheet(source);
 $('#grind-form').onsubmit=singleSubmit(async e=>{e.preventDefault();const value=e.target.elements.setting.value.trim();try{parseGrind(r.equipment,value);grindDrafts.set(grindKey(r),value);await closeSheet();render();}catch(error){toast(error.message);}});
 $('#reset-grind').onclick=async()=>{grindDrafts.delete(grindKey(r));await closeSheet();render();};
}
async function storePhoto(beanId,image){
 const previous=data('photo').filter(x=>x.beanId===beanId),created=new Date(Math.max(Date.now(),...previous.map(x=>Date.parse(x.created)+1))).toISOString(),photo={id:crypto.randomUUID(),beanId,image,created};
 await merge([{id:photo.id,kind:'photo',created,payload:JSON.stringify(photo)}],scope());
 // A replacement/removal purges old image bytes; the empty latest record is a tombstone for older backups.
 await new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite');for(const p of previous)tx.objectStore('entries').delete([scope(),p.id]);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});entries=await list(scope());
}
function editPhoto(beanId,onUse){
 const existing=beanId?bagPhoto(beanId):'',source=beanId?document.querySelector(`[data-photo-bean="${beanId}"]`):$('#add-bag-photo');let img=null,encoded=existing,serial=0,savingPhoto=false;
 modal(`<p class="eyebrow">YOUR BAG, ON YOUR DEVICE</p><h2>A familiar face on the shelf.</h2><p class="muted">Choose a photo or use your phone camera. Adjust the crop below.</p><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"><div class="photo-crop"><canvas id="photo-canvas" width="480" height="640" aria-label="Bag photo crop preview"></canvas></div><div id="photo-adjust" hidden><label>Zoom<input id="photo-zoom" type="range" min="1" max="3" step="0.01" value="1"></label><label>Horizontal position<input id="photo-x" type="range" min="0" max="1" step="0.01" value="0.5"></label><label>Vertical position<input id="photo-y" type="range" min="0" max="1" step="0.01" value="0.5"></label></div><p class="field-help" id="photo-status">JPEG, PNG or WebP, up to 15 MB. Photos stay here and are included in your backup.</p><div class="actions"><button type="button" id="use-photo" class="primary" ${existing?'':'disabled'}>Save photo</button><button type="button" id="remove-photo">Remove photo</button></div>`);
 $('#dialog').classList.add('photo-dialog');morphSheet(source);
 const canvas=$('#photo-canvas'),ctx=canvas.getContext('2d');
 const draw=()=>{if(!img)return;const zoom=Number($('#photo-zoom').value),ratio=Math.max(480/img.width,640/img.height)*zoom,w=480/ratio,h=640/ratio;ctx.drawImage(img,(img.width-w)*Number($('#photo-x').value),(img.height-h)*Number($('#photo-y').value),w,h,0,0,480,640);let q=.86;do{encoded=canvas.toDataURL('image/jpeg',q);q-=.12;}while(encoded.length>240000&&q>.1);if(encoded.length>240000){encoded='';$('#photo-status').textContent='This photo is too detailed to save. Try a closer crop.';}else $('#photo-status').textContent='Ready · cropped and compressed on this device.';$('#use-photo').disabled=!encoded;};
 for(const id of ['photo-zoom','photo-x','photo-y'])$('#'+id).oninput=draw;
 if(existing){const preview=new Image();preview.onload=()=>ctx.drawImage(preview,0,0,480,640);preview.src=existing;}
 $('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++serial;$('#use-photo').disabled=true;encoded='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw Error('Choose a JPEG, PNG or WebP photo under 15 MB.');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this photo.'));reader.readAsDataURL(file);});const decoded=new Image();await new Promise((resolve,reject)=>{decoded.onload=resolve;decoded.onerror=()=>reject(Error('This photo could not be opened. Try a JPEG or PNG.'));decoded.src=url;});if(token!==serial||!canvas.isConnected||!$('#dialog').open)return;if(decoded.width*decoded.height>60000000)throw Error('Choose a photo smaller than 60 megapixels.');img=decoded;$('#photo-zoom').value=1;$('#photo-x').value=$('#photo-y').value=.5;$('#photo-adjust').hidden=false;draw();}catch(error){$('#photo-status').textContent=error.message;}};
 const apply=async image=>{if(savingPhoto)return;savingPhoto=true;const button=$('#use-photo'),remove=$('#remove-photo');button.disabled=remove.disabled=true;try{if(beanId)await storePhoto(beanId,image);else onUse(image);await closeSheet();if(beanId)render();}catch(error){toast(error.message);}finally{savingPhoto=false;button.disabled=!encoded;remove.disabled=false;}};
 $('#use-photo').onclick=()=>{if(encoded)apply(encoded);};$('#remove-photo').onclick=()=>apply('');
}

// A single human action produces one durable record, even during a slow disk write.
const pendingForms=new WeakSet();
function singleSubmit(handler){return async event=>{event.preventDefault();const form=event.currentTarget;if(pendingForms.has(form))return;pendingForms.add(form);const buttons=[...form.querySelectorAll('button[type=submit],button:not([type])')],states=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);try{await handler(event);}finally{pendingForms.delete(form);buttons.forEach((b,i)=>b.disabled=states[i]);}};}
function canReplaceBrew(){return !recipe||seconds()===0||confirm('Discard the unfinished cup and start a new one?');}
function privacyPage(){const content=globalThis.DAYCUP_BUNDLE?.privacy;$('#main').innerHTML=content||'<section class="panel"><h1>Your coffee stays here.</h1><a href="privacy.html">Read the privacy & data notice</a></section>';}
function studioWelcome(hasSetup,hasBeans){
 $('#main').innerHTML=`<section class="welcome-studio"><p class="eyebrow">A DAILY RITUAL, A LITTLE BETTER</p><div class="welcome-objects">${equipmentObject('brewer')}${beanObject({name:'Your next favourite',roast:'medium'})}</div><h1>${hasSetup?'Now, the good part.':'Make a little room<br>for coffee.'}</h1><p>${hasSetup?'Add the bag you’re opening. We’ll take it from there.':'Your beans. Your familiar setup.<br>A place to remember what tastes right.'}</p><div class="welcome-steps"><span class="${hasSetup?'complete':''}">01 <b>Your setup</b>${hasSetup?' ✓':''}</span><i></i><span class="${hasBeans?'complete':''}">02 <b>Your beans</b>${hasBeans?' ✓':''}</span></div><a class="button primary" href="#${hasSetup?'beans':'equipment'}">${hasSetup?'Add your beans':'Add your setup'}</a><small>Saved here, cup after cup.</small></section>`;
}

