function timerHTML(){return `<div class="timer">${dialFace(clockText(seconds()),'BREW TIME',recipe.equipment.method==='v60'?300:60,seconds(),true)}<p id="brew-step" class="muted" role="status" aria-live="polite">${t('Start timing from {basis}',{basis:basis(recipe.equipment.method)})}</p><div class="actions"><button id="timer-toggle" class="primary">${t(timerStart?'Pause':'Start timer')}</button><button id="finish">${t('Done brewing · save this cup')}</button></div></div>`;}
function seconds(){return elapsed+(timerStart?(Date.now()-timerStart)/1000:0);}
function bindTimer(){if(!$('#timer-toggle'))return;$('#timer-toggle').onclick=()=>{if(timerStart){elapsed=seconds();timerStart=null;}else timerStart=Date.now();$('#timer-toggle').textContent=t(timerStart?'Pause':'Start timer');nativeCheckpoint();nativeSend('haptic');};$('#finish').onclick=()=>{elapsed=seconds();timerStart=null;nativeCheckpoint();feedbackPage();};}
setInterval(()=>{const out=$('#timer');if(out){const s=Math.max(0,Math.floor(seconds()));out.textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}const face=$('.ritual-dial[data-limit]');if(face){face.querySelector('.dial-hand').setAttribute('transform',`rotate(${-90+Math.min(seconds()/Number(face.dataset.limit),1)*180} 160 164)`);}const step=$('#brew-step');if(step&&recipe){const n=seconds(),p=recipe.pours?.find(p=>n<p.until);const text=n===0?t('Start timing from {basis}',{basis:basis(recipe.equipment.method)}):p?t('{label} · {total} g cumulative water by {until} sec',{label:p.label,total:p.totalG,until:p.until}):recipe.pours?t('Let it draw down. Diagnostic window: {min}–{max} sec.',{min:recipe.timeMin,max:recipe.timeMax}):recipe.timeDiagnostic===false?t('Stop at {output} g espresso. Pressurized basket: log elapsed time only; no single-wall time target.',{output:recipe.output}):t('Stop at {output} g espresso; {min}–{max} sec is a diagnostic window, not an instruction to keep brewing past the yield.',{output:recipe.output,min:recipe.timeMin,max:recipe.timeMax});if(step.textContent!==text)step.textContent=text;}},250);
function feedbackPage(){
 const snapshot=structuredClone(recipe),captured=scope(),diluted=['americano','iced-americano'].includes(snapshot.drink);
 modal(`<p class="eyebrow">${escape(snapshot.bean.name)} · ${snapshot.dose} g in / ${snapshot.output} g out</p><h2>${t('How was your cup?')}</h2><form id="feedback">${tasteChoices(diluted)}<div class="row">${input(t('Actual dose / g'),'dose',snapshot.dose,'number','min="0.1" max="100" step="0.1" required')}${input(t(snapshot.equipment.method==='espresso'?'Actual espresso yield / g':'Actual water / g'),'output',snapshot.output,'number','min="0.1" max="2000" step="0.1" required')}</div>${input(t('Brew time / seconds'),'seconds',Math.round(elapsed)||'','number','min="1" max="3600" step="1" required')}${input('Grind setting (optional)','grindSetting',draftGrind(snapshot),'text','maxlength="100" aria-describedby="grind-setting-help"')}<p id="grind-setting-help" class="field-help">Record the setting you used. For a multi-part dial, include its turns or offset.</p>${draftGrind(snapshot)?check('I used this grind setting for this cup','grindConfirmed'):''}${diluted?`${check(t('I tasted a small sample of the espresso before dilution'),'tastedBase')}<div class="row">${input(t(snapshot.drink==='americano'?'Actual hot water / g':'Actual cold water / g'),'waterG',snapshot.serving.waterG,'number','min="0" max="2000" step="0.1" required')}${input(t(snapshot.drink==='americano'?'Ice / g (hot drink: 0)':'Actual ice / g'),'iceG',snapshot.serving.iceG,'number',snapshot.drink==='americano'?'min="0" max="0" readonly required':'min="0" max="2000" step="0.1" required')}</div>${check(t('I weighed the dilution water and ice (zero for hot Americano)'),'servingConfirmed')}<label>${t('Finished drink strength')}<select name="strength">${option({balanced:'Just right',weak:'Too weak',strong:'Too strong'},'balanced')}</select></label>`:''}${check(t('The flow or pour was even, with no obvious channeling'),'even')}${check(t('I timed from {basis}',{basis:basis(snapshot.equipment.method)}),'timingConfirmed')}${check(t('I brewed this cup and tasted it'),'observed')}<label>${t('A note for next time (optional)')}<textarea name="notes" maxlength="2000"></textarea></label><button class="primary">${t('Save cup & see what to try')}</button></form>`);
 $('#dialog').classList.add('feedback-dialog');morphSheet($('.timer .dial-display'));
 $('#feedback').onsubmit=singleSubmit(async e=>{e.preventDefault();try{if(captured!==scope())throw Error(t('Your account changed. Please start again.'));const f=new FormData(e.target),feedback={dose:Number(f.get('dose')),output:Number(f.get('output')),seconds:Number(f.get('seconds')),taste:f.get('taste'),even:f.has('even'),timingConfirmed:f.has('timingConfirmed'),observed:f.has('observed'),notes:f.get('notes'),grindSetting:f.get('grindSetting').trim(),...(diluted?{tastedBase:f.has('tastedBase'),servingConfirmed:f.has('servingConfirmed'),waterG:Number(f.get('waterG')),iceG:Number(f.get('iceG')),strength:f.get('strength')}:{})};if(feedback.grindSetting&&draftGrind(snapshot)&&!f.has('grindConfirmed'))throw Error('Confirm the grind setting you actually used.');if(!feedback.observed)throw Error(t('Please confirm that you brewed and tasted this cup.'));const measured=captureBrewRecipe(snapshot,feedback),decision=adjust(measured,feedback),b={id:crypto.randomUUID(),created:new Date().toISOString(),recipe:measured,feedback,decision};await save('brew',b);recipe=null;timerStart=null;elapsed=0;nativeCheckpoint();grindDrafts.delete(grindKey(snapshot));$('#dialog-content').innerHTML=`<p class="eyebrow">${t(decision.status==='keep'?'SAVED / A KEEPER':'SAVED / NEXT TIME')}</p><h2>${escape(decision.message)}</h2><p>${t('This cup is saved on your device.')}</p><button class="primary" id="next-cup">Back to my next cup</button> <a class="button" id="to-history" href="#history">${t('See my brews')}</a>`;$('#next-cup').onclick=()=>{recipe=null;$('#dialog').close();render();};$('#to-history').onclick=()=>$('#dialog').close();}catch(error){toast(error.message);}});
}
