  $('[name="catalog-search"]').oninput=drawSearch;
  document.querySelectorAll('[data-featured]').forEach(button=>button.onclick=()=>{const x=featured.find(x=>x.id===button.dataset.featured);$('#dialog').close();onChoose(x.brand,x.model);});
  document.querySelectorAll('[data-brand]').forEach(button=>button.onclick=()=>showModels(brands.find(b=>b.id===button.dataset.brand)));
