 form.onsubmit=singleSubmit(async e=>{e.preventDefault();try{const f=new FormData(form),bean={name:f.get('name'),roast:f.get('roast'),origin:f.get('origin'),process:f.get('process'),species:f.get('species'),caffeine:f.get('caffeine'),variety:f.get('variety').trim(),robustaPercent:f.get('robustaPercent')!==''?Number(f.get('robustaPercent')):null,roastedOn:f.get('roastedOn'),batch:f.get('batch'),id:crypto.randomUUID(),blend:f.has('blend')};if(f.has('labelEnabled'))bean.labelRecipe={method:f.get('labelMethod'),dose:Number(f.get('labelDose')),output:Number(f.get('labelOutput')),...(f.get('labelTemperature')?{temperatureC:Number(f.get('labelTemperature'))}:{}),...(f.get('labelTimeMin')||f.get('labelTimeMax')?{timeMin:Number(f.get('labelTimeMin')),timeMax:Number(f.get('labelTimeMax'))}:{})};if(newBagPhoto){const now=new Date().toISOString(),photo={id:crypto.randomUUID(),beanId:bean.id,image:newBagPhoto,created:now};await merge([{id:bean.id,kind:'bean',created:now,payload:JSON.stringify(bean)},{id:photo.id,kind:'photo',created:now,payload:JSON.stringify(photo)}],scope());entries=await list(scope());}else await save('bean',bean);selected.bean=bean.id;render();toast(t('Beans saved. Time for a cup.'));}catch(error){toast(error.message);}});
