function historyPage(){
 const cups=data('brew'),days=new Set(cups.map(x=>new Date(x.created).toLocaleDateString('sv-SE'))).size;
 $('#main').innerHTML=`<div class="lead"><p class="eyebrow">${t('TASTE, ADJUST, REPEAT')}</p><h1>${t('Small notes.<br>Better mornings.')}</h1></div><section class="journal-summary"><div><strong>${cups.length}</strong><span>${cups.length===1?'cup recorded':'cups recorded'}</span></div><p><b>${days}</b> ${days===1?'brew day':'brew days'} <span>·</span> <b>${data('bean').length}</b> ${data('bean').length===1?'bag saved':'bags saved'}</p></section><section class="panel"><label class="check"><input type="checkbox" id="favorites">${t('Show favorites only')}</label><div id="brews"></div></section>`;
 const show=()=>{$('#brews').innerHTML=data('brew').sort((a,b)=>b.created.localeCompare(a.created)).filter(b=>!$('#favorites').checked||b.decision.status==='keep').map(b=>`<article class="item"><span class="badge">${escape(t(tastes[b.feedback.taste]))}</span><h3>${escape(b.recipe.bean.name)}</h3><p class="muted">${escape(t(drinks[b.recipe.drink]||methods[b.recipe.equipment.method]))} · ${b.feedback.output} g · ${Math.round(b.feedback.seconds)} ${t('sec')} · ${escape(b.created.slice(0,10))}</p><p>${escape(b.decision.message)}</p><button data-brew="${b.id}">${t('Open brew')}</button></article>`).join('')||`<div class="empty"><h2>${t('Your next cup belongs here.')}</h2><p class="muted">${t('After brewing, save the measured dose, output, time and taste.')}</p><a class="button primary" href="#brew">${t('Brew a cup')}</a></div>`;document.querySelectorAll('[data-brew]').forEach(button=>button.onclick=()=>{const b=data('brew').find(x=>x.id===button.dataset.brew);modal(card(b.recipe)+`<p>${t('Measured: {dose} g dose / {output} g output / {seconds} sec',{dose:b.feedback.dose,output:b.feedback.output,seconds:Math.round(b.feedback.seconds)})}</p><h3>${escape(b.decision.message)}</h3><p>${escape(b.feedback.notes)}</p>`);});studioHistory();};show();$('#favorites').onchange=show;
}
async function withBusy(task){if(busy)return;busy=true;document.querySelectorAll('#main button').forEach(b=>b.disabled=true);try{await task();}catch(error){toast(error.message);}finally{busy=false;render();}}
function downloadJSON(value,name){
 if(globalThis.DAYCUP_NATIVE){nativeSend('export',{name,text:JSON.stringify(value,null,2)});return;}
 const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function dataPage(){
 $('#main').innerHTML=`<div class="lead"><p class="eyebrow">${t('YOUR COFFEE, YOUR RECORDS')}</p><h1>${t('On this device. Yours.')}</h1><p class="muted">${t('{setups} setups · {batches} batches · {brews} brews',{setups:data('equipment').length,batches:data('bean').length,brews:data('brew').length})}</p></div><div class="grid"><section class="panel"><h2>${t('No account. No AI. No API key.')}</h2><p>${t('Recipes and suggestions are calculated here using fixed, versioned rules. No sign-up, subscriptions, tracking SDKs or automatic uploads.')}</p><p class="hint">${t('This is not cloud storage. Moving this HTML file, changing browser or opening another device does not transfer your records. Export a backup first.')}</p><div class="actions"><button class="primary" id="export">${t('Export backup')}</button><button id="import">${t('Import backup')}</button></div><input id="file" type="file" accept="application/json,.json" hidden><p class="muted">${t('Backups include your private notes and history. Share them only with people you trust. Import merges compatible records without duplicates or silent overwrites.')}</p><button id="persist">${t('Request persistent storage')}</button><p class="muted">${t('Your browser can decline this request. Browser cleanup, private browsing and device loss can still remove data; keep a separate backup.')}</p><button class="danger" id="clear-local">${t('Clear this local library')}</button></section><div><section class="panel"><h2>${t('Two ways to keep Daycup')}</h2><p><strong>${t('On the web:')}</strong> ${t('open Daycup at its SideCourt address. On a phone, use Add to Home Screen to keep it as an app icon; on a desktop browser, use Install app. After the first visit it works offline.')}</p><p><strong>${t('As a file:')}</strong> ${t('keep the standalone Daycup.html file and open it in a desktop browser. Everything it needs is included. If your browser blocks file storage, use the included loopback launcher instead.')}</p><p class="muted">${t('Records stay in the browser where you saved them. Each address, browser and device has its own library; move records with Export and Import.')}</p><p class="muted">Daycup ${escape(appVersion)} · ${escape(knowledgeVersion)} · ${t('Espresso, Americano, iced Americano and V60. Actual basket capacity and grinder calibration still need your confirmation. A software test is not a taste test.')}</p><p class="muted"><a href="${globalThis.DAYCUP_BUNDLE?'#privacy':'privacy.html'}">${t('Privacy & data')}</a></p></section><section class="panel"><h2>${t('Previous local libraries')}</h2><p class="muted">${t('An older version may have kept records under an account on this same browser. They remain separate and untouched. No password or server connection is used here.')}</p><button id="legacy">${t('Recover a library on my device')}</button><p class="muted">${t('Use only your own browser profile. Local records are not encrypted or protected from other people using this profile.')}</p></section></div></div>`;
 document.querySelectorAll('[data-language]').forEach(button=>button.onclick=()=>{setLanguage(button.dataset.language);applyChrome();render();});
 $('#export').onclick=()=>downloadJSON({schema:1,entries},'Daycup-backup-'+localToday()+'.json');
 $('#import').onclick=()=>globalThis.DAYCUP_NATIVE?nativeSend('import'):$('#file').click();$('#file').onchange=e=>{const file=e.target.files[0];if(!file)return;withBusy(async()=>{if(file.size>16000000)throw Error(t('The backup exceeds 16 MB.'));const archive=JSON.parse(await file.text());if(archive.schema!==1)throw Error(t('This backup version is not supported.'));await merge(archive.entries,scope());entries=await list(scope());toast(t('Backup imported. Matching records were not duplicated.'));});};
 $('#persist').onclick=async()=>{try{const granted=await navigator.storage?.persist?.();toast(t(granted?'Persistent storage granted. Still keep a backup.':'Persistent storage was not granted by this browser. Export a backup regularly.'));}catch{toast(t('This browser cannot grant persistent storage here. Export a backup.'));}};
 $('#clear-local').onclick=()=>{modal(`<h2>${t('Clear this local library?')}</h2><p>${t('Export a backup first. There is no automatic cloud copy. Only the current local library will be removed; old separate libraries remain.')}</p><button class="danger" id="confirm-clear">${t('Permanently clear this library')}</button>`);$('#confirm-clear').onclick=()=>withBusy(async()=>{await clearScope(scope());entries=[];grindDrafts.clear();recipe=null;timerStart=null;$('#dialog').close();toast(t('The current local library has been cleared.'));});};
 $('#legacy').onclick=async()=>{try{
  const rows=await new Promise((resolve,reject)=>{const r=db.transaction('entries').objectStore('entries').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
  const groups=[...new Set(rows.map(x=>x.scope))].filter(x=>x!==scope());
  modal(`<h2>${t('Recover only your own records')}</h2><p>${t('Local libraries are not a login security boundary. Select a library you own. Exporting does not merge or delete it. Import that backup separately to copy it into the current library.')}</p>${groups.map((g,i)=>`<p><button data-legacy="${i}">${t('Export previous library {number} · {count} records',{number:i+1,count:rows.filter(x=>x.scope===g).length})}</button></p>`).join('')||'<p>'+t('No previous account libraries were found on this browser and address.')+'</p>'}`);
  document.querySelectorAll('[data-legacy]').forEach(button=>button.onclick=()=>{const g=groups[Number(button.dataset.legacy)];if(confirm(t('I own this local library and want to export its private records.')))downloadJSON({schema:1,entries:rows.filter(x=>x.scope===g).map(({scope,...entry})=>entry)},'Daycup-previous-library-'+localToday()+'.json');});
 }catch(error){toast(error.message);}};
 studioData();
 if(globalThis.DAYCUP_NATIVE)nativeDataPage();
}
window.addEventListener('beforeunload',event=>{if(recipe&&seconds()>0){event.preventDefault();event.returnValue='';}});

// The iPhone host reuses the same validated library and recipe engine.
function nativePrivacyPage(){
 $('#main').innerHTML='<p class="eyebrow">PRIVACY & LOCAL DATA</p><h1>Your coffee stays here.</h1><p>Daycup calculates recipes on your iPhone. There are no accounts, analytics SDKs, advertisements, AI requests or automatic uploads of your coffee records.</p><p>Your equipment, beans, photos, recipes and notes are stored in this app. Photos you select are cropped and compressed on your device. Removing a photo removes it from the current library; older backups keep their original photos.</p><p>Backups contain your notes and photos in readable JSON. You choose where to save or share them using the iOS share sheet. Files or cloud services you select follow their own privacy policies.</p><p>Your iPhone may include app data in its system backups, according to your device settings. Daycup has no separate cloud sync. Deleting the app or losing your phone can remove local records. Save a separate backup in Files.</p><p>Manufacturer and other external links open only when you tap them. Those websites have their own privacy policies.</p><a class="button" href="#data">Back to settings</a>';
}
function nativeDataPage(){
 const primary=$('.data-primary');if(primary){const hint=primary.querySelector('.hint');if(hint)hint.textContent='Your library stays on this iPhone. Save a backup to Files before replacing your phone or deleting the app.';}
 const persist=$('#persist');if(persist){const note=persist.nextElementSibling;if(note)note.textContent='Deleting Daycup or losing this iPhone can remove your library. Keep a separate backup in Files.';persist.hidden=true;}
 const sections=[...$('#main').querySelectorAll('section')];const install=sections.find(x=>x.querySelector('h2')?.textContent==='Two ways to keep Daycup');if(install)install.innerHTML='<h2>Made for your daily cup.</h2><p>Daycup works offline. Your equipment, coffee bags, photos and brewing notes stay in this app.</p><p>Use Keep a backup to save your library to Files or share it. Bring it back restores a Daycup JSON backup, including backups from the web edition.</p><p>Daycup 2.3 · Espresso, Americano, iced Americano and V60.</p><a href="#privacy">Privacy & data</a>';
}
function nativeSend(action,payload={}){if(!globalThis.DAYCUP_NATIVE)return;globalThis.webkit?.messageHandlers?.daycup?.postMessage({action,...payload});}
function nativeCheckpoint(){
 if(!globalThis.DAYCUP_NATIVE)return;
 try{if(recipe)localStorage.setItem('daycup-active-cup',JSON.stringify({recipe,selected,elapsed,timerStart,grindDrafts:[...grindDrafts]}));else localStorage.removeItem('daycup-active-cup');}catch(error){toast('Your active timer could not be saved. Finish this cup before closing Daycup.');}
 nativeSend('timer',{running:!!timerStart});
}
function restoreNativeCup(){
 try{const raw=localStorage.getItem('daycup-active-cup');if(!raw)return;const v=JSON.parse(raw);if(!v.recipe?.equipment?.id||!v.recipe?.bean?.id||!Number.isFinite(v.elapsed)||v.elapsed<0||v.timerStart!==null&&!Number.isFinite(v.timerStart))return;if(!data('equipment').some(e=>e.id===v.recipe.equipment.id)||!data('bean').some(b=>b.id===v.recipe.bean.id))return;recipe=v.recipe;selected=v.selected;elapsed=v.elapsed;timerStart=v.timerStart;if(Array.isArray(v.grindDrafts))for(const pair of v.grindDrafts){if(Array.isArray(pair)&&pair.length===2&&typeof pair[0]==='string'&&typeof pair[1]==='string')grindDrafts.set(...pair);}nativeSend('timer',{running:!!timerStart});}catch(error){toast('The unfinished cup could not be restored. Your saved library is still available.');}
}
if(globalThis.DAYCUP_NATIVE){
 document.documentElement.classList.add('native-app');
 globalThis.daycupNative={
  navigate(route){if(!['brew','beans','history','equipment','data','privacy'].includes(route))return;location.hash=route;},
  async importBackup(text){try{if(new Blob([text]).size>16000000)throw Error('The backup exceeds 16 MB.');const archive=JSON.parse(text);if(archive.schema!==1)throw Error('This backup version is not supported.');await merge(archive.entries,scope());entries=await list(scope());render();toast('Backup restored. Matching records were not duplicated.');nativeSend('haptic');}catch(error){toast(error.message);}},
  checkpoint:nativeCheckpoint,
  notify(message){toast(message);}
 };
 document.addEventListener('visibilitychange',nativeCheckpoint);

}

window.addEventListener('hashchange',()=>{render();$('#main').focus();});
window.addEventListener('offline',()=>connection('Offline · Saved on this device'));
window.addEventListener('online',()=>connection('On this device · No automatic uploads'));
try {
 applyChrome();
 db=await openDB();entries=await list(scope());
 const bundled=globalThis.DAYCUP_BUNDLE;
 const load=async name=>{const r=await fetch('./'+name);if(!r.ok)throw Error(t('Cannot load {name}',{name}));return r.json();};
 const results=await Promise.allSettled([bundled?Promise.resolve(bundled.equipment):load('equipment-directory.json'),bundled?Promise.resolve(bundled.beans):load('bean-options.json')]);
 if(results[0].status==='fulfilled'){equipmentDirectory=curatedDirectory(results[0].value);initializeKnowledge(equipmentDirectory);}
 if(results[1].status==='fulfilled')beanOptions=results[1].value;
 if(globalThis.DAYCUP_NATIVE)restoreNativeCup();
 render();connection(bundled?'Offline file · No account':'Saved on this device · No account');
 if(!equipmentDirectory||!beanOptions)toast(t('Some directory choices could not load. You can still enter your own equipment and beans.'));
 if(!bundled&&'serviceWorker' in navigator&&['http:','https:'].includes(location.protocol)){
  navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'}).then(registration=>{const announce=()=>{if(registration.waiting&&navigator.serviceWorker.controller)toast('Update ready. Finish your cup, then close all Daycup tabs and reopen. Your records stay on this device.');};announce();registration.addEventListener('updatefound',()=>{registration.installing?.addEventListener('statechange',announce);});return navigator.serviceWorker.ready;}).then(()=>connection('Ready offline · Records on this device')).catch(()=>toast(t('Offline caching could not be installed. Keep this page open and export your records.')));
 }
}catch(error){$('#main').innerHTML=`<h1>${t('We could not open your local records.')}</h1><p>${t('Check that your browser allows sites to save data. Your existing records have not been reset. For a downloaded file, try the included loopback launcher.')}</p>`;toast(error.message);}
